"kind": "propose",
"summary": "The container 'app' is consistently hitting its CPU limit (200m) with 91.5% usage, causing throttling. Increasing the CPU limit to 300m should alleviate this.",
"hypotheses": [
  {
    "root_cause_class": "cpu_limit_too_low",
    "summary": "CPU limit is too low, causing sustained throttling.",
    "supporting": ["ev-container_cpu", "ev-container_logs_tail"],
    "contradicting": [],
    "missing": [],
    "status": "supported"
  }
],
"proposal": {
  "capability": "deployment.set-resources",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "search",
    "uid": "uid-deployment-search"
  },
  "params": {
    "containers": {
      "app": {
        "limits": {
          "cpu": "300m"
        }
      }
    }
  },
  "expected_effect": "The container 'app' will have its CPU limit increased to 300m, reducing throttling and improving performance.",
  "rationale": "The container is consistently hitting its CPU limit (200m) with 91.5% usage, causing throttling. Increasing the limit to 1.5 times the current value (300m) should provide sufficient headroom to avoid throttling.",
  "cited_evidence_ids": ["ev-container_cpu", "ev-container_logs_tail"],
  "cited_predicates": ["throttling_data_available", "cpu_throttled_at_limit", "cpu_usage_near_limit"]
}
}
